import { asset_sub_category } from "@/graphql/mutations.js";
import { asset_categories } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    categoriessubEddition: Boolean,
    categoriesItem: Object,
    rowInfo: Object
  },
  data() {
    return {
      categoriesName: "",
      depreciationCode: "",
      categoryitems: [],
      maincategories: "",
      loading: false,
      categoriesdescription: "",
      depreciationitems: Array.from({
        length: 100
      }, (_, i) => i + 1)
    };
  },
  watch: {
    categoriessubEddition: {
      async handler() {
        if (this.categoriessubEddition == true) {
          this.categoriesName = this.categoriesItem.text;
          this.depreciationCode = this.categoriesItem.sub_category_depriciation == undefined ? this.rowInfo.category_depriciation : this.categoriesItem.sub_category_depriciation;
        }
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
      this.$refs.form.resetValidation();
      this.$refs.form.reset();
    },
    async validate_data() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        this.add_mutation();
      }
    },
    async add_mutation() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(asset_sub_category, {
          input: {
            user_email_id: data.user.user_email_id,
            action_type: "UPDATE_SUBCATEGORY",
            category_id: this.rowInfo.category_id,
            sub_category_name: this.categoriesName,
            sub_category_depriciation: Number(this.depreciationCode),
            // sub_category_description: this.categoriesdescription,
            sub_category_id: this.categoriesItem.value
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.asset_sub_category);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
